with tempfile.TemporaryDirectory(prefix='nubialy-date-') as work:
    work=Path(work)
    for name,content in sources.items():
        p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
    files=[str(p) for p in work.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy/ClockDatePolicy.java'),str(root/'app/src/main/java/com/elitedarkkaiser/nubialy/xposed/ClockDateBackend.java')]
    subprocess.run(['java','com.sun.tools.javac.Main','-d',str(work/'classes'),*files],check=True)
    for args in [[],['restore-failure']]:subprocess.run(['java','-cp',str(work/'classes'),'com.elitedarkkaiser.nubialy.xposed.DateTest',*args],check=True)
